-- Wisconsin had sixteen stops.
--
-- Five dropped as duplicates, every one a world's-largest object already here
-- under a different spelling: Six Pack against Six-Pack, Potato Masher against
-- a longer name for the same masher.
--
-- Kept despite flagging: the Museum of Root Beer and the Museum of Historic
-- Torture Devices are both within three hundred metres of the Haunted Mansion,
-- because that is what the Wisconsin Dells strip is like.
--
-- Tennessee, Alabama and Mississippi are Central time; so are Illinois,
-- Wisconsin and Louisiana. No county exceptions in any of the six.
--
-- 125 stops.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Hodag Statue and Hodag Store', 'hodag-statue-and-hodag-store', 'cryptids', 45.63892, -89.41236, 'Rhinelander', 'WI', 'The Hodag is Rhinelander''s horned, tusked hometown monster, born from late-19th-century lumber-camp folklore and Eugene Shepard''s famous 1896 hoax photograph. The Chamber grounds give travelers a permanent giant Hodag statue, visitor information and a concrete stop tied directly to the legend.', 'open', 'https://www.explorerhinelander.com/hodag/', 'https://www.explorerhinelander.com/', 'America/Chicago', now()),
  ('Beast of Bray Road', 'beast-of-bray-road', 'cryptids', 42.68185, -88.4828, 'Elkhorn', 'WI', 'Bray Road became nationally known after reports of a large wolf-like or upright canine creature were collected around Elkhorn beginning in the late 1980s. The legend is now one of Wisconsin''s signature cryptid stories. Treat the road as a normal public roadway: do not stop unsafely or enter private property.', 'roadside', 'https://www.atlasobscura.com/places/bray-road-2', 'https://www.visitwalworthcounty.com/', 'America/Chicago', now()),
  ('Elmwood UFO Days and UFO Sighting Area', 'elmwood-ufo-days-and-ufo-sighting-area', 'ufos', 44.77939, -92.15131, 'Elmwood', 'WI', 'Elmwood built an unusual civic identity around a series of reported UFO sightings, including a well-known 1975 account involving a local police officer. The village''s annual UFO Days festival celebrates the lore with alien-themed events and gives OddWay a lawful public anchor for a story otherwise spread across rural roads.', 'limited', 'https://ufodays.net/', 'https://ufodays.net/', 'America/Chicago', now()),
  ('Belleville UFO Day and 1987 Sighting Story', 'belleville-ufo-day-and-1987-sighting-story', 'ufos', 42.85972, -89.53818, 'Belleville', 'WI', 'Belleville commemorates a January 1987 incident in which local residents and police reported unusual lights in the sky. The village now leans into the story with UFO Day, alien decorations and community programming, making downtown a practical public stop tied to the sighting lore.', 'limited', 'https://bellevillewi.com/ufo/', 'https://bellevillewi.com/', 'America/Chicago', now()),
  ('Bloody Bride Bridge Legend — Highway 66', 'bloody-bride-bridge-legend-highway-66', 'folklore', 44.56094, -89.49938, 'Stevens Point', 'WI', 'Local legend says a bride died in a crash on Highway 66 near Jordan Park and still appears along the road, sometimes in mirrors or beside passing cars. The story is folklore rather than documented paranormal fact. Visitors should experience it only from lawful public areas and never stop in a dangerous traffic location.', 'roadside', 'https://www.stevenspointarea.com/blog/stories/post/spooky-stevens-point-area/', 'https://www.stevenspointarea.com/', 'America/Chicago', now()),
  ('The Pfister Hotel', 'the-pfister-hotel', 'haunted', 43.03944, -87.90572, 'Milwaukee', 'WI', 'Milwaukee''s grand 1893 Pfister Hotel has accumulated decades of ghost stories, including reports from visiting professional athletes who have described unexplained noises, moving objects and apparitions. It remains a functioning luxury hotel, so the paranormal reputation can be experienced without treating the building like an abandoned haunt.', 'open', 'https://www.thepfisterhotel.com/', 'https://www.thepfisterhotel.com/', 'America/Chicago', now()),
  ('Dartford Cemetery', 'dartford-cemetery', 'haunted', 43.8522, -88.96538, 'Green Lake', 'WI', 'This historic cemetery has become one of Green Lake''s best-known paranormal folklore locations, with stories of strange lights, apparitions and unexplained sounds. The claims remain local legend, but the cemetery itself is a real historic site. Visit respectfully during lawful cemetery hours.', 'limited', 'https://www.cityofgreenlake.com/', 'https://www.cityofgreenlake.com/', 'America/Chicago', now()),
  ('Forest Home Cemetery', 'forest-home-cemetery', 'weird-history', 43.00301, -87.94459, 'Milwaukee', 'WI', 'Forest Home is one of Milwaukee''s great historic cemeteries, filled with elaborate monuments and the graves of major figures from the city''s brewing, industrial and political history. Local ghost stories have attached themselves to the landscape, but its stronger OddWay value is the dense collection of unusual monuments and Milwaukee history.', 'limited', 'https://foresthomecemetery.com/', 'https://foresthomecemetery.com/', 'America/Chicago', now()),
  ('Dells Ghost Boat', 'dells-ghost-boat', 'haunted', 43.62794, -89.77825, 'Wisconsin Dells', 'WI', 'This nighttime attraction carries visitors by boat into the sandstone landscape of the Wisconsin Dells before continuing through dark wooded and canyon environments built around regional ghost stories. It is a ticketed seasonal experience rather than an unsupervised haunted-location visit.', 'limited', 'https://www.dellsghostboat.com/', 'https://www.dellsghostboat.com/', 'America/Chicago', now()),
  ('Lake Geneva Ghost Walk', 'lake-geneva-ghost-walk', 'haunted', 42.58804, -88.43075, 'Lake Geneva', 'WI', 'Guided ghost walks use downtown Lake Geneva''s historic streets, hotels and lakefront stories as the setting for local legends, unexplained events and darker pieces of community history. Tours operate on scheduled dates, giving travelers a structured way to explore the city''s paranormal folklore.', 'limited', 'https://www.americanghostwalks.com/wisconsin/lake-geneva-ghost-walks/', 'https://www.americanghostwalks.com/', 'America/Chicago', now()),
  ('Big Musky and National Fresh Water Fishing Hall of Fame', 'big-musky-and-national-fresh-water-fishing-hall-of-fame', 'roadside-oddities', 46.00773, -91.47934, 'Hayward', 'WI', 'The museum''s landmark is an enormous fiberglass muskellunge large enough for visitors to walk inside and climb to an observation platform in its mouth. The surrounding Fishing Hall of Fame adds displays of record catches, boats, tackle and freshwater-angling history.', 'open', 'https://www.freshwater-fishing.org/', 'https://www.freshwater-fishing.org/', 'America/Chicago', now()),
  ('Al Johnson''s Goats on the Roof', 'al-johnsons-goats-on-the-roof', 'roadside-oddities', 45.18987, -87.11996, 'Sister Bay', 'WI', 'Al Johnson''s Swedish Restaurant became a Door County icon after goats began grazing on its sod-covered roof. The living rooftop spectacle, Scandinavian architecture and adjacent Goat Cam turn an operating restaurant into one of Wisconsin''s most recognizable roadside attractions.', 'open', 'https://aljohnsons.com/', 'https://aljohnsons.com/', 'America/Chicago', now()),
  ('Pinkie the Pink Elephant', 'pinkie-the-pink-elephant', 'roadside-oddities', 43.25761, -89.33579, 'DeForest', 'WI', 'A giant pink fiberglass elephant wearing glasses stands beside County Highway V, a surviving piece of classic roadside advertising that has become a local landmark in its own right. It is best treated as a quick photo stop from the business property or other lawful public areas.', 'roadside', 'https://www.travelwisconsin.com/stories/photo-ops-and-quirky-stops-14-must-see-wisconsin-roadside-attractions', 'https://www.travelwisconsin.com/', 'America/Chicago', now()),
  ('Mars Cheese Castle', 'mars-cheese-castle', 'roadside-oddities', 42.61461, -87.95444, 'Kenosha', 'WI', 'This castle-shaped cheese shop near I-94 combines Wisconsin food culture with deliberately oversized roadside architecture. Turrets, a throne, cheese displays and a gift-heavy interior make it much more than a normal highway store.', 'open', 'https://www.marscheese.com/', 'https://www.marscheese.com/', 'America/Chicago', now()),
  ('Claire d''Loon', 'claire-dloon', 'roadside-oddities', 46.16448, -90.06023, 'Mercer', 'WI', 'Mercer''s enormous fiberglass loon, Claire d''Loon, celebrates the town''s identity as the Loon Capital of the World. The bird stands roughly two stories tall and makes an unmistakable roadside photo stop beside the visitor center.', 'roadside', 'https://www.mercercc.com/', 'https://www.mercercc.com/', 'America/Chicago', now()),
  ('Sputnik IV Crash Site Marker', 'sputnik-iv-crash-site-marker', 'weird-history', 44.09883, -87.6577, 'Manitowoc', 'WI', 'A brass ring embedded in North 8th Street marks where a fragment associated with the Soviet Sputnik IV spacecraft crashed back to Earth in 1962. Manitowoc later embraced the bizarre Cold War incident with the annual Sputnikfest celebration.', 'open', 'https://www.manitowoc.org/', 'https://www.manitowoc.org/', 'America/Chicago', now()),
  ('World''s Largest M', 'worlds-largest-m', 'roadside-oddities', 42.76371, -90.40667, 'Platteville', 'WI', 'A huge white letter M built from limestone sits on a hillside overlooking Platteville. University of Wisconsin-Platteville students created the monument to represent the region''s mining heritage, and trails allow visitors to approach the giant letter.', 'open', 'https://www.uwplatt.edu/', 'https://www.uwplatt.edu/', 'America/Chicago', now()),
  ('Dr. Evermor''s Forevertron', 'dr-evermors-forevertron', 'roadside-oddities', 43.3637, -89.77085, 'North Freedom', 'WI', 'Artist Tom Every transformed salvaged industrial machinery into the Forevertron, a massive retro-futurist sculpture imagined as a device that could launch its creator into the heavens. The surrounding art park is packed with metal birds, machines and other outsider-art constructions.', 'limited', 'https://www.worldofdrevermor.com/', 'https://www.worldofdrevermor.com/', 'America/Chicago', now()),
  ('Ben Bikin''', 'ben-bikin', 'roadside-oddities', 43.93902, -90.8095, 'Sparta', 'WI', 'Sparta''s giant cyclist celebrates the town''s long connection to bicycle manufacturing and its identity as the Bicycling Capital of America. The oversized figure stands downtown as an easy public photo stop.', 'open', 'https://www.bikesparta.us/', 'https://www.bikesparta.us/', 'America/Chicago', now()),
  ('Wisconsin Concrete Park', 'wisconsin-concrete-park', 'roadside-oddities', 45.67136, -90.39039, 'Phillips', 'WI', 'Fred Smith spent years covering concrete figures with glass, mirrors, stones and found objects, creating a roadside environment populated by lumberjacks, animals, historical figures and scenes from local life. The preserved sculpture park is one of Wisconsin''s major vernacular-art environments.', 'open', 'https://www.wisconsinconcretepark.org/', 'https://www.wisconsinconcretepark.org/', 'America/Chicago', now()),
  ('Chatty Belle and Wisconsin Pavilion', 'chatty-belle-and-wisconsin-pavilion', 'roadside-oddities', 44.55315, -90.58052, 'Neillsville', 'WI', 'Chatty Belle is a giant fiberglass dairy cow whose recorded voice once explained Wisconsin''s dairy industry to visitors. She stands beside the Wisconsin Pavilion, a surviving World''s Fair structure that was moved to Neillsville after the 1964 New York World''s Fair.', 'limited', 'https://www.neillsville.org/', 'https://www.neillsville.org/', 'America/Chicago', now()),
  ('World''s Largest Soup Kettle', 'worlds-largest-soup-kettle', 'roadside-oddities', 45.56485, -88.75746, 'Laona', 'WI', 'An enormous metal kettle beside U.S. 8 is a relic of Laona''s lumber-camp identity and has long been promoted as the world''s largest soup kettle. Its exaggerated scale makes it an easy old-school roadside photo stop.', 'roadside', 'https://www.roadsideamerica.com/tip/1426', 'https://www.laonawisconsin.info/', 'America/Chicago', now()),
  ('Rhinelapus', 'rhinelapus', 'roadside-oddities', 45.57678, -89.15872, 'Monico', 'WI', 'This giant jackalope-like roadside creature combines a rabbit body with antlers and has become known as the Rhinelapus. It is exactly the kind of improbable fiberglass animal OddWay is built for, but visitors should view it only from safe lawful areas near the roadside property.', 'roadside', 'https://www.roadsideamerica.com/location/wi/all', 'https://www.roadsideamerica.com/location/wi/all', 'America/Chicago', now()),
  ('World''s Largest Badger', 'worlds-largest-badger', 'roadside-oddities', 44.99042, -89.20452, 'Birnamwood', 'WI', 'A huge badger statue towers beside the highway in Birnamwood, turning Wisconsin''s state nickname into a literal roadside giant. The fiberglass figure is a simple but highly visible photo stop.', 'roadside', 'https://www.roadsideamerica.com/tip/1425', 'https://www.roadsideamerica.com/tip/1425', 'America/Chicago', now()),
  ('Marty the Musky', 'marty-the-musky', 'roadside-oddities', 46.11131, -89.64668, 'Boulder Junction', 'WI', 'Boulder Junction''s giant musky statue celebrates the community''s self-proclaimed status as the Musky Capital of the World. The fish stands in town as a public landmark and a compact stop for Wisconsin''s obsession with oversized freshwater creatures.', 'open', 'https://boulderjct.org/why-is-boulder-junction-the-musky-capital-of-the-world/', 'https://boulderjct.org/', 'America/Chicago', now()),
  ('World''s Only Pulpwood Stacker', 'worlds-only-pulpwood-stacker', 'weird-history', 45.16614, -91.15512, 'Cornell', 'WI', 'A preserved mechanical pulpwood stacker rises over Mill Yard Park, once used to pile enormous quantities of cut timber for the paper industry. Its skeletal machinery makes it look like industrial sculpture while preserving a highly specific piece of Wisconsin logging technology.', 'open', 'https://www.roadsideamerica.com/tip/1428', 'https://www.cityofcornell.com/', 'America/Chicago', now()),
  ('Igor the Cheese-Loving Rat', 'igor-the-cheese-loving-rat', 'roadside-oddities', 42.97723, -90.65551, 'Fennimore', 'WI', 'A giant fiberglass rat clutching cheese stands outside a Fennimore cheese business, leaning fully into Wisconsin''s dairy identity. The oversized rodent is a classic highway-photo oddity rather than a formal attraction.', 'roadside', 'https://www.roadsideamerica.com/tip/21372', 'https://www.roadsideamerica.com/tip/21372', 'America/Chicago', now()),
  ('Original Giant Hex Nut', 'original-giant-hex-nut', 'roadside-oddities', 44.46672, -88.06794, 'Green Bay', 'WI', 'This enormous industrial fastener was long promoted as the world''s largest hex nut. Larger examples have since appeared elsewhere, so OddWay should present it as the original famous Green Bay giant rather than an uncontested current record-holder.', 'roadside', 'https://www.roadsideamerica.com/tip/53193', 'https://www.roadsideamerica.com/tip/53193', 'America/Chicago', now()),
  ('World''s Tallest Grandfather Clock', 'worlds-tallest-grandfather-clock', 'roadside-oddities', 44.46012, -87.50378, 'Kewaunee', 'WI', 'A four-faced clock tower built to resemble an enormous grandfather clock stands near the Kewaunee harbor. The whimsical structure functions as public art, a timepiece and one of the city''s signature landmarks.', 'open', 'https://www.kewaunee.org/grandfather-clock', 'https://www.kewaunee.org/', 'America/Chicago', now()),
  ('World''s Largest Corkscrew', 'worlds-largest-corkscrew', 'roadside-oddities', 46.45071, -90.19623, 'Hurley', 'WI', 'An enormous corkscrew sculpture rises outside a Hurley business along U.S. 2. Its exaggerated spiral silhouette makes a strange punctuation mark along a Northwoods highway better known for mines, forests and snow.', 'roadside', 'https://www.roadsideamerica.com/tip/12354', 'https://www.roadsideamerica.com/tip/12354', 'America/Chicago', now()),
  ('Tiki Cheesehead', 'tiki-cheesehead', 'roadside-oddities', 44.47259, -88.45045, 'Black Creek', 'WI', 'A giant carved figure combines Wisconsin''s cheesehead identity with exaggerated tiki-style roadside art. It is a deliberately goofy photo stop that works best as a short roadside detour.', 'roadside', 'https://www.roadsideamerica.com/location/wi/all', 'https://www.roadsideamerica.com/location/wi/all', 'America/Chicago', now()),
  ('Rock in the House', 'rock-in-the-house', 'weird-history', 44.14124, -91.73086, 'Fountain City', 'WI', 'In 1995, a massive boulder broke from the bluff and crashed directly into this house. Rather than remove the rock, the owners preserved the damage as a tiny museum, leaving the enormous stone lodged inside the building where it came to rest.', 'limited', 'https://www.roadsideamerica.com/story/2880', 'https://www.roadsideamerica.com/story/2880', 'America/Chicago', now()),
  ('45°N 90°W Geographic Marker', '45-n-90-w-geographic-marker', 'roadside-oddities', 45, -90, 'Poniatowski', 'WI', 'Near Poniatowski, the 45th parallel north meets the 90th meridian west—halfway between the Equator and North Pole and one-quarter of the way around the globe from Greenwich. A marker and small park turn an otherwise invisible grid intersection into a physical destination.', 'open', 'https://www.marathoncounty.gov/', 'https://www.marathoncounty.gov/', 'America/Chicago', now()),
  ('Da Crusher Statue', 'da-crusher-statue', 'roadside-oddities', 42.91028, -87.86289, 'South Milwaukee', 'WI', 'A bronze statue honors professional wrestler Reggie ''Da Crusher'' Lisowski, the beer-drinking, blue-collar wrestling icon closely associated with South Milwaukee. Fans crowdfunded the memorial, which now stands publicly in his hometown.', 'open', 'https://www.roadsideamerica.com/story/65895', 'https://www.southmilwaukee.gov/', 'America/Chicago', now()),
  ('Andy Gump Statue', 'andy-gump-statue', 'roadside-oddities', 42.58949, -88.43413, 'Lake Geneva', 'WI', 'A bronze statue honors cartoon character Andy Gump and his creator Sidney Smith, who had strong ties to the Lake Geneva area. The public monument is a niche pilgrimage point for early newspaper-comic history.', 'open', 'https://www.roadsideamerica.com/story/11771', 'https://www.visitlakegeneva.com/', 'America/Chicago', now()),
  ('Mount Horeb Trollway', 'mount-horeb-trollway', 'folklore', 43.00634, -89.73408, 'Mount Horeb', 'WI', 'Mount Horeb has filled its downtown with carved trolls inspired by Scandinavian folklore, earning the nickname Troll Capital of the World. The figures line the Trollway and turn an ordinary Main Street stroll into a scavenger hunt of wooden creatures.', 'open', 'https://www.trollway.com/', 'https://www.trollway.com/', 'America/Chicago', now()),
  ('Giant Speared Sturgeon — George W. Brown Jr. Ojibwe Museum', 'giant-speared-sturgeon-george-w-brown-jr-ojibwe-museum', 'roadside-oddities', 45.96941, -89.89262, 'Lac du Flambeau', 'WI', 'A giant speared sturgeon sculpture outside the museum connects immediately to the Lac du Flambeau community''s fishing traditions. Inside, exhibits interpret Ojibwe history and culture, giving the oversized fish a much richer context than a stand-alone roadside statue.', 'open', 'https://www.roadsideamerica.com/tip/10426', 'https://www.lacduflambeau.com/', 'America/Chicago', now()),
  ('Bronze Fonz', 'bronze-fonz', 'roadside-oddities', 43.04038, -87.91099, 'Milwaukee', 'WI', 'A life-size bronze Arthur ''Fonzie'' Fonzarelli stands beside the Milwaukee River, commemorating the fictional Happy Days character whose show was set in Milwaukee. Visitors can pose beside the permanently frozen thumbs-up.', 'open', 'https://www.roadsideamerica.com/story/18990', 'https://www.visitmilwaukee.org/', 'America/Chicago', now()),
  ('Cray-1 Supercomputer — Chippewa Falls Museum of Industry & Technology', 'cray-1-supercomputer-chippewa-falls-museum-of-industry-technology', 'roadside-oddities', 44.93697, -91.39258, 'Chippewa Falls', 'WI', 'Chippewa Falls helped launch the era of supercomputing through Seymour Cray''s work. The museum preserves a Cray-1 and other computing hardware whose curved cabinets and dense wiring look almost sculptural beside today''s tiny electronics.', 'limited', 'https://www.cfmit.org/', 'https://www.cfmit.org/', 'America/Chicago', now()),
  ('Lottie Cooper Shipwreck Remains', 'lottie-cooper-shipwreck-remains', 'weird-history', 43.75319, -87.70368, 'Sheboygan', 'WI', 'Timbers from the schooner Lottie Cooper, wrecked in an 1894 storm, were recovered during harbor construction and reassembled outdoors near the waterfront. The exposed wooden skeleton lets visitors walk around the remains of a nineteenth-century Great Lakes ship on dry land.', 'open', 'https://www.wisconsinshipwrecks.org/Vessel/Details/385', 'https://www.wisconsinshipwrecks.org/', 'America/Chicago', now()),
  ('Sunny the Sunfish', 'sunny-the-sunfish', 'roadside-oddities', 43.89211, -91.23917, 'Onalaska', 'WI', 'A huge bluegill/sunfish statue overlooks Lake Onalaska from a public park. The oversized fish celebrates the area''s angling culture and makes an easy stop along the Mississippi River corridor.', 'open', 'https://www.explorelacrosse.com/', 'https://www.explorelacrosse.com/', 'America/Chicago', now()),
  ('F.A.S.T. Fiberglass Mold Graveyard', 'fast-fiberglass-mold-graveyard', 'roadside-oddities', 43.96874, -90.78208, 'Sparta', 'WI', 'Hundreds of weathered molds used to manufacture America''s giant fiberglass roadside figures are stored in an outdoor field at F.A.S.T. Fiberglass. Visitors can walk among molds for animals, characters, food and Muffler Men; the owners ask guests not to climb on them and to watch for insects.', 'open', 'https://www.fastfiberglass.com/', 'https://www.fastfiberglass.com/', 'America/Chicago', now()),
  ('Birthplace of the Snowmobile — Vilas County Historical Museum', 'birthplace-of-the-snowmobile-vilas-county-historical-museum', 'weird-history', 45.98502, -89.53136, 'Sayner', 'WI', 'Sayner celebrates Carl Eliason''s 1924 motor toboggan, an important ancestor of the modern snowmobile. The local museum preserves early machines and Northwoods history, turning a tiny community into a pilgrimage point for snowmobile enthusiasts.', 'limited', 'https://www.vilashistorical.com/', 'https://www.vilashistorical.com/', 'America/Chicago', now()),
  ('Ice Cream Sundae Birthplace Marker — Washington House Museum', 'ice-cream-sundae-birthplace-marker-washington-house-museum', 'weird-history', 44.15389, -87.56933, 'Two Rivers', 'WI', 'Two Rivers claims that the first ice cream sundae was served here in 1881. A marker and the Washington House Museum preserve the local version of the origin story, which remains disputed by other communities but has become a durable piece of American food folklore.', 'limited', 'https://www.tworiverseconomicdevelopment.org/', 'https://www.tworivershistory.org/', 'America/Chicago', now()),
  ('Dungeons & Dragons — Gary Gygax Memorial Plaque', 'dungeons-dragons-gary-gygax-memorial-plaque', 'roadside-oddities', 42.59113, -88.43391, 'Lake Geneva', 'WI', 'Lake Geneva was the home base of Gary Gygax and the early tabletop-gaming community that produced Dungeons & Dragons. A public plaque commemorates Gygax and the city''s outsized role in creating modern role-playing games.', 'open', 'https://www.visitlakegeneva.com/', 'https://www.visitlakegeneva.com/', 'America/Chicago', now()),
  ('National Mustard Museum', 'national-mustard-museum', 'museums', 43.09539, -89.51111, 'Middleton', 'WI', 'This museum treats mustard with scholarly seriousness and comic enthusiasm, displaying thousands of jars from around the world alongside advertising, history and tasting opportunities. The gift shop and tasting bar make it one of Wisconsin''s most accessible odd museums.', 'open', 'https://mustardmuseum.org/', 'https://mustardmuseum.org/', 'America/Chicago', now()),
  ('National Bobblehead Hall of Fame and Museum', 'national-bobblehead-hall-of-fame-and-museum', 'museums', 43.02972, -87.91056, 'Milwaukee', 'WI', 'Thousands of nodding figures fill display cases devoted to sports, celebrities, mascots, politics and pop culture. The museum also documents the history and manufacture of bobbleheads, turning a novelty collectible into an improbably comprehensive archive.', 'open', 'https://www.bobbleheadhall.com/', 'https://www.bobbleheadhall.com/', 'America/Chicago', now()),
  ('A World of Accordions Museum', 'a-world-of-accordions-museum', 'museums', 46.72086, -92.09826, 'Superior', 'WI', 'A former church houses hundreds of accordions and related free-reed instruments from many countries and eras. The sheer density of ornate, mechanical instruments makes the museum both a music archive and an unusually specific visual collection.', 'limited', 'https://www.worldofaccordions.org/', 'https://www.worldofaccordions.org/', 'America/Chicago', now()),
  ('Deke Slayton Memorial Space & Bicycle Museum', 'deke-slayton-memorial-space-bicycle-museum', 'museums', 43.94468, -90.81269, 'Sparta', 'WI', 'This small-town museum combines two subjects that rarely share a building: astronaut Deke Slayton''s space career and Sparta''s bicycle-manufacturing heritage. Space hardware, astronaut material and historic bikes make the pairing uniquely OddWay.', 'limited', 'https://dekeslaytonmuseum.org/', 'https://dekeslaytonmuseum.org/', 'America/Chicago', now()),
  ('Dinosaur Discovery Museum', 'dinosaur-discovery-museum', 'museums', 42.5839, -87.82367, 'Kenosha', 'WI', 'Skeletons and casts focus on the evolutionary link between meat-eating dinosaurs and modern birds. The museum''s dramatic central displays include large theropod skeletons, while an on-site laboratory shows how fossils are prepared and studied.', 'open', 'https://museums.kenosha.org/dinosaur-discovery-museum', 'https://museums.kenosha.org/', 'America/Chicago', now()),
  ('Harley-Davidson Museum', 'harley-davidson-museum', 'museums', 43.03182, -87.91639, 'Milwaukee', 'WI', 'Harley-Davidson''s museum preserves motorcycles ranging from the company''s earliest machines to racing bikes, custom motorcycles and famous one-offs. The industrial campus and rows of historic machines make it a strong mechanical-history stop even for travelers who are not riders.', 'open', 'https://www.harley-davidson.com/us/en/experiences/museum.html', 'https://www.harley-davidson.com/us/en/experiences/museum.html', 'America/Chicago', now()),
  ('National Dairy Shrine and Hoard Historical Museum', 'national-dairy-shrine-and-hoard-historical-museum', 'museums', 42.92376, -88.83591, 'Fort Atkinson', 'WI', 'The Hoard Historical Museum includes the National Dairy Shrine, a collection devoted to the people, cattle, equipment and ideas that shaped the American dairy industry. In Wisconsin, a museum that treats dairy history as a national shrine feels entirely appropriate.', 'limited', 'https://www.hoardmuseum.org/', 'https://www.hoardmuseum.org/', 'America/Chicago', now()),
  ('Castlerock Museum', 'castlerock-museum', 'museums', 44.3197, -91.91374, 'Alma', 'WI', 'Rows of arms, armor and historical weapons fill this privately built museum overlooking the Mississippi River. Exhibits span centuries and cultures, including suits of armor, swords and polearms that make the collection feel more like a castle armory than a small-town museum.', 'limited', 'https://www.castlerockmuseum.com/', 'https://www.castlerockmuseum.com/', 'America/Chicago', now()),
  ('National Railroad Museum', 'national-railroad-museum', 'museums', 44.48312, -88.04789, 'Green Bay', 'WI', 'Historic locomotives and railcars fill this large museum, including streamlined, military and luxury passenger equipment. Visitors can walk through selected cars and see the immense scale of machines that shaped American transportation.', 'open', 'https://nationalrrmuseum.org/', 'https://nationalrrmuseum.org/', 'America/Chicago', now()),
  ('National Brewery Museum at Potosi Brewery', 'national-brewery-museum-at-potosi-brewery', 'museums', 42.67694, -90.72556, 'Potosi', 'WI', 'A restored historic brewery houses a museum devoted to American brewing and brewery advertising. Neon signs, bottles, trays and brewery artifacts make the collection a dense archive of an industry deeply tied to Wisconsin identity.', 'open', 'https://www.potosibrewery.com/museums', 'https://www.potosibrewery.com/', 'America/Chicago', now()),
  ('Peshtigo Fire Museum and Mass Grave', 'peshtigo-fire-museum-and-mass-grave', 'weird-history', 45.05576, -87.75386, 'Peshtigo', 'WI', 'The museum preserves artifacts and accounts from the October 8, 1871 Peshtigo Fire, the deadliest wildfire in recorded U.S. history. Beside it, a mass grave holds unidentified victims, creating a powerful and somber stop that should be visited respectfully.', 'limited', 'https://peshtigofiremuseum.com/', 'https://peshtigofiremuseum.com/', 'America/Chicago', now()),
  ('Mining & Rollo Jamison Museums', 'mining-rollo-jamison-museums', 'museums', 42.73271, -90.47321, 'Platteville', 'WI', 'Platteville''s museum complex combines regional history with an underground lead-and-zinc mining experience. Guided tours descend into the 1845 Bevans Lead Mine, giving visitors a tangible look at the industry that shaped southwest Wisconsin.', 'limited', 'https://mining.jamison.museum/', 'https://mining.jamison.museum/', 'America/Chicago', now()),
  ('Snowmobile Hall of Fame', 'snowmobile-hall-of-fame', 'museums', 45.90828, -89.48965, 'St. Germain', 'WI', 'Historic racing sleds, pioneering machines, trophies and memorabilia fill a museum dedicated to snowmobiling. The collection fits naturally in the Northwoods, where the machine became both transportation and winter culture.', 'limited', 'https://www.snowmobilehalloffame.com/museum/', 'https://www.snowmobilehalloffame.com/', 'America/Chicago', now()),
  ('Wisconsin Cranberry Discovery Center', 'wisconsin-cranberry-discovery-center', 'museums', 44.13094, -90.50057, 'Warrens', 'WI', 'Located in one of the state''s major cranberry-growing areas, this museum explains how the fruit is cultivated, harvested and processed. Historic equipment and agricultural displays turn an everyday juice ingredient into a surprisingly specialized Wisconsin story.', 'limited', 'https://www.discovercranberries.com/', 'https://www.discovercranberries.com/', 'America/Chicago', now()),
  ('History Museum at the Castle', 'history-museum-at-the-castle', 'museums', 44.26186, -88.40216, 'Appleton', 'WI', 'A dramatic former Masonic temple now houses local-history exhibits, including material on Appleton native Harry Houdini. The castle-like building and recurring focus on magic, invention and Fox Valley history make it more unusual than a conventional county museum.', 'open', 'https://www.myhistorymuseum.org/', 'https://www.myhistorymuseum.org/', 'America/Chicago', now()),
  ('Circus World', 'circus-world', 'museums', 43.46695, -89.7371, 'Baraboo', 'WI', 'Baraboo was winter headquarters for the Ringling Brothers, and Circus World preserves historic circus buildings, wagons, posters, costumes and performance traditions on the original grounds. Seasonal live programming turns the site into both a museum and a surviving fragment of circus culture.', 'limited', 'https://circusworld.wisconsinhistory.org/', 'https://circusworld.wisconsinhistory.org/', 'America/Chicago', now()),
  ('Art Preserve', 'art-preserve', 'museums', 43.74306, -87.75472, 'Sheboygan', 'WI', 'This museum was built specifically to house artist-built environments and vernacular art that would otherwise be difficult to preserve. Entire rooms and large fragments from outsider-art sites are reconstructed inside, making the building feel like a warehouse of transplanted worlds.', 'open', 'https://www.jmkac.org/art-preserve/', 'https://www.jmkac.org/art-preserve/', 'America/Chicago', now()),
  ('Spinning Top & Yo-Yo Museum', 'spinning-top-yo-yo-museum', 'museums', 42.67863, -88.27698, 'Burlington', 'WI', 'A small museum is devoted almost entirely to spinning tops, yo-yos and related kinetic toys. Demonstrations and hands-on displays turn simple childhood objects into a deep dive on balance, motion and toy history.', 'limited', 'https://www.topmuseum.org/', 'https://www.topmuseum.org/', 'America/Chicago', now()),
  ('Wisconsin Automotive Museum', 'wisconsin-automotive-museum', 'museums', 43.32023, -88.38097, 'Hartford', 'WI', 'The museum specializes in Wisconsin-connected automobiles, especially Kissel cars once built in Hartford. Historic vehicles share the building with engines and transportation displays, preserving a lesser-known chapter of the state''s manufacturing history.', 'open', 'https://wisconsinautomuseum.com/', 'https://wisconsinautomuseum.com/', 'America/Chicago', now()),
  ('EAA Aviation Museum', 'eaa-aviation-museum', 'museums', 43.984, -88.57726, 'Oshkosh', 'WI', 'Oshkosh''s aviation museum displays experimental aircraft, warbirds, early planes and one-of-a-kind flying machines. Its connection to the enormous annual EAA AirVenture gathering makes the site a pilgrimage point for unusual aircraft and homebuilt-flight culture.', 'open', 'https://www.eaa.org/eaa-museum', 'https://www.eaa.org/eaa-museum', 'America/Chicago', now()),
  ('Twig''s Beverage Museum', 'twigs-beverage-museum', 'museums', 44.77471, -88.60924, 'Shawano', 'WI', 'Twig''s preserves the history of Sun Drop and the local bottling business through vintage bottles, machinery, advertising and soda memorabilia. Visitors can watch bottling activity and sample soda, making it a working-industry museum rather than a static display.', 'open', 'https://twigsbeverage.net/', 'https://twigsbeverage.net/', 'America/Chicago', now()),
  ('Wisconsin Maritime Museum and USS Cobia', 'wisconsin-maritime-museum-and-uss-cobia', 'museums', 44.09295, -87.65566, 'Manitowoc', 'WI', 'The museum''s centerpiece is USS Cobia, a World War II submarine permanently moored on the Manitowoc River. Visitors can tour the cramped vessel while learning how Manitowoc shipyards built submarines for the war effort.', 'open', 'https://www.wisconsinmaritime.org/', 'https://www.wisconsinmaritime.org/', 'America/Chicago', now()),
  ('Museum of Historic Torture Devices', 'museum-of-historic-torture-devices', 'museums', 43.62668, -89.77317, 'Wisconsin Dells', 'WI', 'This compact museum displays replicas and historical examples of punishment and torture devices, pairing grim subject matter with downtown Wisconsin Dells tourism. The attraction operates seasonally, so hours should be checked before routing.', 'limited', 'https://torturemuseumdells.com/', 'https://torturemuseumdells.com/', 'America/Chicago', now()),
  ('Museum of Root Beer', 'museum-of-root-beer', 'museums', 43.62692, -89.7727, 'Wisconsin Dells', 'WI', 'A museum dedicated entirely to root beer covers brands, bottling, advertising and the drink''s place in American soda culture. Hundreds of labels and artifacts make an everyday soft drink into an unexpectedly deep collecting obsession.', 'open', 'https://museumofrootbeer.com/', 'https://museumofrootbeer.com/', 'America/Chicago', now()),
  ('SafeHouse Milwaukee', 'safehouse-milwaukee', 'roadside-oddities', 43.04071, -87.91125, 'Milwaukee', 'WI', 'This spy-themed restaurant hides behind a deliberately secretive entrance and fills its interior with espionage props, passages, gadgets and Cold War-style jokes. Guests without the password may have to prove themselves before entering, making dinner part attraction and part interactive gag.', 'open', 'https://www.safe-house.com/', 'https://www.safe-house.com/', 'America/Chicago', now()),
  ('International Clown Hall of Fame and Research Center', 'international-clown-hall-of-fame-and-research-center', 'museums', 43.47115, -89.74273, 'Baraboo', 'WI', 'This museum preserves costumes, props, portraits, tiny cars and archival material from notable clowns and circus performers. Located in circus-heavy Baraboo, it gives OddWay a concentrated collection devoted to one of entertainment history''s strangest professions.', 'open', 'https://www.theclownmuseum.com/', 'https://www.theclownmuseum.com/', 'America/Chicago', now()),
  ('Dr. Kate Museum', 'dr-kate-museum', 'museums', 45.89546, -89.70031, 'Woodruff', 'WI', 'The museum tells the story of physician Kate Pelham Newcomb and the community penny drive that helped fund a hospital in the 1950s. It adds human context to the nearby giant penny and preserves the unusual publicity campaign that put tiny Woodruff in national headlines.', 'limited', 'https://www.drkatemuseum.org/', 'https://www.drkatemuseum.org/', 'America/Chicago', now()),
  ('Rahr-West Art Museum', 'rahr-west-art-museum', 'museums', 44.09772, -87.65668, 'Manitowoc', 'WI', 'A Victorian mansion and modern gallery addition contain fine art, decorative objects and local-history material. The grounds also connect directly with Manitowoc''s Sputnik story, making the museum a useful stop for both art and space-age weird history.', 'open', 'https://www.rahrwestartmuseum.org/', 'https://www.rahrwestartmuseum.org/', 'America/Chicago', now()),
  ('SS Meteor Whaleback Ship Museum', 'ss-meteor-whaleback-ship-museum', 'museums', 46.68934, -92.01955, 'Superior', 'WI', 'SS Meteor is the last surviving example of the unusual whaleback cargo-ship design developed for Great Lakes service. The vessel''s rounded cigar-like hull can be toured seasonally at Barker''s Island.', 'limited', 'https://www.superiorwi.gov/60/SS-Meteor', 'https://www.superiorhistoricproperties.org/', 'America/Chicago', now()),
  ('Camp Five Museum and Lumberjack Steam Train', 'camp-five-museum-and-lumberjack-steam-train', 'museums', 45.56359, -88.67187, 'Laona', 'WI', 'A vintage steam train carries visitors from Laona to a preserved logging-camp museum complex. Historic machinery, camp buildings and forestry exhibits make the ride feel like a functioning fragment of Northwoods industrial history.', 'limited', 'https://www.lumberjacksteamtrain.com/', 'https://www.lumberjacksteamtrain.com/', 'America/Chicago', now()),
  ('The House on the Rock', 'the-house-on-the-rock', 'roadside-oddities', 43.10016, -90.13577, 'Spring Green', 'WI', 'Alex Jordan Jr.''s sprawling complex combines impossible-looking architecture with rooms packed with automated music machines, model ships, armor, giant creatures, circus displays and the enormous indoor carousel. Few American attractions match its scale of deliberate sensory overload.', 'limited', 'https://www.thehouseontherock.com/', 'https://www.thehouseontherock.com/', 'America/Chicago', now()),
  ('Mary Nohl Art Environment', 'mary-nohl-art-environment', 'roadside-oddities', 43.15659, -87.89076, 'Fox Point', 'WI', 'Artist Mary Nohl transformed her lakeside property with concrete figures, painted surfaces, sculptures and handmade objects until the entire home became an art environment. The property is preserved but not a normal walk-in attraction; view only from lawful public areas unless attending an authorized program.', 'limited', 'https://www.spacesarchives.org/explore/search-the-online-collection/mary-nohl-art-environment/', 'https://www.jmkac.org/', 'America/Chicago', now()),
  ('Dickeyville Grotto', 'dickeyville-grotto', 'roadside-oddities', 42.62738, -90.59507, 'Dickeyville', 'WI', 'Father Mathias Wernerus covered shrines with colored glass, stones, shells, fossils and found objects to create a dense devotional landscape beside Holy Ghost Church. Religious imagery mixes with patriotic symbols and glittering folk-art surfaces.', 'open', 'https://www.dickeyvillegrotto.com/', 'https://www.dickeyvillegrotto.com/', 'America/Chicago', now()),
  ('Rudolph Grotto Gardens', 'rudolph-grotto-gardens', 'roadside-oddities', 44.4991, -89.80063, 'Rudolph', 'WI', 'Hand-built stone shrines, winding paths and religious tableaux spread through several acres beside St. Philip Church. Local rock, shells and decorative masonry turn the grounds into one of Wisconsin''s major Catholic folk-art environments.', 'open', 'https://www.rudolphgrotto.org/', 'https://www.rudolphgrotto.org/', 'America/Chicago', now()),
  ('Wegner Grotto', 'wegner-grotto', 'roadside-oddities', 44.08774, -90.84236, 'Cataract', 'WI', 'Paul and Matilda Wegner covered concrete forms with glass, ceramics and found materials to build a miniature chapel, fanciful structures and sculptural monuments. The preserved environment looks like a mosaic dream hidden among rural fields.', 'limited', 'https://www.monroecountyhistory.org/wegner-grotto', 'https://www.monroecountyhistory.org/', 'America/Chicago', now()),
  ('Prairie Moon Sculpture Garden', 'prairie-moon-sculpture-garden', 'roadside-oddities', 44.19721, -91.79899, 'Fountain City', 'WI', 'Retired farmer Herman Rusch created dozens of concrete and found-object sculptures across his property, including animals, people and whimsical constructions. The site is preserved as an outdoor folk-art environment and museum.', 'limited', 'https://www.kohlerfoundation.org/preservation/major-preservation-projects/prairie-moon-sculpture-garden-and-museum/', 'https://www.kohlerfoundation.org/', 'America/Chicago', now()),
  ('Nick Engelbert''s Grandview', 'nick-engelberts-grandview', 'roadside-oddities', 42.87345, -89.94726, 'Hollandale', 'WI', 'Immigrant farmer Nick Engelbert surrounded his home with colorful concrete sculptures depicting animals, people, fairy tales and family memories. The restored site preserves both the sculpture garden and the painted house.', 'limited', 'https://nicksgrandview.com/', 'https://nicksgrandview.com/', 'America/Chicago', now()),
  ('Jurustic Park', 'jurustic-park', 'roadside-oddities', 44.73561, -90.16676, 'Marshfield', 'WI', 'Clyde Wynia builds whimsical metal creatures from scrap and presents them as the fossilized remains of extinct creatures from the fictional Jurustic Age. Dragons, insects and impossible animals fill the outdoor property in a mix of sculpture and deadpan mythology.', 'limited', 'https://jurustic.com/', 'https://jurustic.com/', 'America/Chicago', now()),
  ('James Tellen Woodland Sculpture Garden', 'james-tellen-woodland-sculpture-garden', 'roadside-oddities', 43.6897, -87.70885, 'Sheboygan', 'WI', 'James Tellen filled his wooded property with hand-built concrete people, animals and religious scenes. The figures emerge between trees like a homemade storybook and are now preserved for public viewing.', 'open', 'https://www.jmkac.org/artist/james-tellen/', 'https://www.jmkac.org/', 'America/Chicago', now()),
  ('Stevens Point Sculpture Park', 'stevens-point-sculpture-park', 'roadside-oddities', 44.54273, -89.57575, 'Stevens Point', 'WI', 'Large contemporary sculptures are scattered along wooded walking trails, so pieces appear unexpectedly between trees rather than inside a gallery. The free outdoor park blends a nature walk with an evolving public-art collection.', 'open', 'https://stevenspoint.com/435/Sculpture-Park', 'https://stevenspoint.com/435/Sculpture-Park', 'America/Chicago', now()),
  ('Kinstone Megalithic Garden', 'kinstone-megalithic-garden', 'folklore', 44.13144, -91.69977, 'Fountain City', 'WI', 'Modern standing stones, stone circles, earthworks, a labyrinth and other monumental landscape features occupy this private garden overlooking the Mississippi River region. The structures are contemporary rather than ancient, but intentionally evoke prehistoric ceremonial landscapes.', 'limited', 'https://www.kinstonecircle.com/', 'https://www.kinstonecircle.com/', 'America/Chicago', now()),
  ('Epic Systems Campus', 'epic-systems-campus', 'roadside-oddities', 42.9964, -89.56854, 'Verona', 'WI', 'The software company''s enormous campus is filled with themed buildings, fantasy interiors, underground passages, giant sculptures and environments inspired by everything from storybooks to science fiction. Visitor access policies should be checked before going because it remains an active workplace.', 'limited', 'https://www.epic.com/visiting/', 'https://www.epic.com/', 'America/Chicago', now()),
  ('Taliesin', 'taliesin', 'roadside-oddities', 43.1411, -90.0704, 'Spring Green', 'WI', 'Frank Lloyd Wright''s home, studio and architectural laboratory evolved over decades on a Wisconsin hillside. Fires, rebuilding and Wright''s unconventional personal history make the estate as complicated as its celebrated architecture.', 'limited', 'https://www.taliesinpreservation.org/', 'https://www.taliesinpreservation.org/', 'America/Chicago', now()),
  ('Monona Terrace Community and Convention Center', 'monona-terrace-community-and-convention-center', 'roadside-oddities', 43.07143, -89.37982, 'Madison', 'WI', 'Frank Lloyd Wright first proposed a civic center for this lakefront site in the 1930s, but the completed building did not open until 1997, decades after his death. The sweeping structure and public rooftop preserve a rare posthumously realized Wright concept.', 'open', 'https://www.mononaterrace.com/', 'https://www.mononaterrace.com/', 'America/Chicago', now()),
  ('Annunciation Greek Orthodox Church', 'annunciation-greek-orthodox-church', 'roadside-oddities', 43.0989, -88.02888, 'Wauwatosa', 'WI', 'One of Frank Lloyd Wright''s final designs reinterprets a Byzantine church through a low circular form and broad blue dome. The building remains an active place of worship, so visitors should use scheduled architectural opportunities or respectfully view the exterior.', 'limited', 'https://www.annunciationwi.org/', 'https://www.annunciationwi.org/', 'America/Chicago', now()),
  ('Holy Hill Basilica and Scenic Tower', 'holy-hill-basilica-and-scenic-tower', 'roadside-oddities', 43.24479, -88.32678, 'Hubertus', 'WI', 'A twin-spired basilica rises above a heavily wooded glacial hill, visible for miles across southeastern Wisconsin. The complex combines pilgrimage shrines, chapels and a seasonal observation tower reached by a long staircase.', 'limited', 'https://www.holyhill.com/', 'https://www.holyhill.com/', 'America/Chicago', now()),
  ('Octagon House Museum', 'octagon-house-museum', 'roadside-oddities', 43.19447, -88.7241, 'Watertown', 'WI', 'Built in 1854, this unusual eight-sided house follows the nineteenth-century fascination with octagonal architecture. Its preserved rooms, central staircase and historic grounds make the geometry itself the main attraction.', 'limited', 'https://www.watertownhistory.org/', 'https://www.watertownhistory.org/', 'America/Chicago', now()),
  ('Ten Chimneys', 'ten-chimneys', 'roadside-oddities', 42.96854, -88.36758, 'Genesee Depot', 'WI', 'Broadway stars Alfred Lunt and Lynn Fontanne turned this estate into a theatrical retreat filled with highly personal rooms, art and stage-world connections. The preserved property feels more like stepping into an eccentric private set than touring a conventional historic house.', 'limited', 'https://www.tenchimneys.org/', 'https://www.tenchimneys.org/', 'America/Chicago', now()),
  ('Don Q Inn — Boeing C-97 and Fantasy Rooms', 'don-q-inn-boeing-c-97-and-fantasy-rooms', 'roadside-oddities', 43.0207, -90.13196, 'Dodgeville', 'WI', 'A retired Boeing C-97 transport plane sits improbably outside this roadside inn, while themed rooms inside include caves, spaceships, hot-air balloons and other elaborate fantasy environments. The combination makes the motel itself an OddWay attraction.', 'open', 'https://www.donqinn.net/', 'https://www.donqinn.net/', 'America/Chicago', now()),
  ('Milwaukee Art Museum — Quadracci Pavilion', 'milwaukee-art-museum-quadracci-pavilion', 'roadside-oddities', 43.03918, -87.89707, 'Milwaukee', 'WI', 'Santiago Calatrava''s lakefront pavilion is topped by a movable brise soleil whose enormous white wings open and close over the building. The kinetic architecture turns a major art museum into a mechanical landmark.', 'open', 'https://mam.org/', 'https://mam.org/', 'America/Chicago', now()),
  ('St. Joan of Arc Chapel', 'st-joan-of-arc-chapel', 'weird-history', 43.03761, -87.931, 'Milwaukee', 'WI', 'A medieval European chapel dismantled and moved to the United States now stands in the middle of Marquette University''s campus. Its stones were reassembled in Milwaukee, creating a genuine piece of medieval architecture in an unexpectedly modern setting.', 'limited', 'https://www.marquette.edu/st-joan-of-arc-chapel/', 'https://www.marquette.edu/st-joan-of-arc-chapel/', 'America/Chicago', now()),
  ('Washington Island Stavkirke', 'washington-island-stavkirke', 'roadside-oddities', 45.36768, -86.93107, 'Washington Island', 'WI', 'This modern wooden church was inspired by medieval Norwegian stave churches, with steep rooflines, carved details and an interior shaped by Scandinavian religious architecture. It reflects Washington Island''s strong Scandinavian heritage.', 'open', 'https://trinitywashingtonisland.org/stavkirke/', 'https://trinitywashingtonisland.org/', 'America/Chicago', now()),
  ('Al. Ringling Theatre', 'al-ringling-theatre', 'roadside-oddities', 43.47111, -89.74361, 'Baraboo', 'WI', 'Al Ringling built this ornate 1915 theater as a lavish gift to Baraboo. Its French-inspired interior, chandeliers, boxes and decorative plasterwork make the venue an unexpectedly grand movie palace in a small Wisconsin city.', 'limited', 'https://alringling.org/', 'https://alringling.org/', 'America/Chicago', now()),
  ('SC Johnson Administration Building and Research Tower', 'sc-johnson-administration-building-and-research-tower', 'roadside-oddities', 42.71352, -87.79047, 'Racine', 'WI', 'Frank Lloyd Wright''s SC Johnson complex uses mushroom-like dendriform columns, curving brick walls and a glass-tube Research Tower that looks unlike a conventional factory headquarters. Interior access is through scheduled company tours.', 'limited', 'https://www.scjohnson.com/en/a-family-company/architecture-and-tours/', 'https://www.scjohnson.com/en/a-family-company/architecture-and-tours/', 'America/Chicago', now()),
  ('Pendarvis', 'pendarvis', 'weird-history', 42.86029, -90.17937, 'Mineral Point', 'WI', 'Stone cottages built by Cornish miners survive along a steep Mineral Point street and now form a Wisconsin Historical Society site. The preserved buildings tell the story of immigration, lead mining and a restoration movement that helped save the town''s unusual architecture.', 'limited', 'https://pendarvis.wisconsinhistory.org/', 'https://pendarvis.wisconsinhistory.org/', 'America/Chicago', now()),
  ('Cave of the Mounds', 'cave-of-the-mounds', 'roadside-oddities', 43.01674, -89.81486, 'Blue Mounds', 'WI', 'Discovered accidentally during quarry blasting in 1939, this limestone cave contains flowstone, stalactites, columns and colorful mineral formations. Guided tours follow paved underground passages through one of Wisconsin''s best-known cave systems.', 'limited', 'https://www.caveofthemounds.com/', 'https://www.caveofthemounds.com/', 'America/Chicago', now()),
  ('Crystal Cave', 'crystal-cave', 'roadside-oddities', 44.83295, -92.2508, 'Spring Valley', 'WI', 'Stairs descend into passages lined with stalactites, flowstone and other limestone formations at Wisconsin''s longest known cave. Guided tours make the underground system accessible without unsupervised caving.', 'limited', 'https://www.acoolcave.org/', 'https://www.acoolcave.org/', 'America/Chicago', now()),
  ('Apostle Islands Meyers Beach Sea Caves', 'apostle-islands-meyers-beach-sea-caves', 'roadside-oddities', 46.81083, -91.09978, 'Cornucopia', 'WI', 'Lake Superior has carved arches, chambers and cliffside caves into the Apostle Islands sandstone. In warm seasons visitors reach overlooks by trail or the caves by water; in rare safe winters ice can transform the formations completely. Conditions must be checked before attempting access.', 'limited', 'https://www.nps.gov/apis/learn/nature/caves.htm', 'https://www.nps.gov/apis/', 'America/Chicago', now()),
  ('Schoolhouse Beach', 'schoolhouse-beach', 'roadside-oddities', 45.39811, -86.92733, 'Washington Island', 'WI', 'Instead of sand, this Lake Michigan beach is covered with smooth white limestone cobbles polished by waves. Removing the distinctive stones is prohibited, so the unusual shoreline should be enjoyed in place.', 'open', 'https://www.washingtonisland-wi.com/', 'https://www.washingtonisland-wi.com/', 'America/Chicago', now()),
  ('Devil''s Doorway', 'devils-doorway', 'roadside-oddities', 43.42514, -89.72837, 'Baraboo', 'WI', 'Two vertical quartzite pillars support a horizontal slab high above Devil''s Lake, forming a natural doorway in the bluff. A steep hiking route reaches the formation, so weather, footwear and trail conditions matter.', 'open', 'https://dnr.wisconsin.gov/topic/parks/devilslake', 'https://dnr.wisconsin.gov/topic/parks/devilslake', 'America/Chicago', now()),
  ('Balanced Rock', 'balanced-rock', 'roadside-oddities', 43.41118, -89.72427, 'Baraboo', 'WI', 'A large quartzite boulder appears to balance precariously atop a narrower pedestal on the East Bluff above Devil''s Lake. The rock is reached by a steep trail and has been a landmark for generations of park visitors.', 'open', 'https://dnr.wisconsin.gov/topic/parks/devilslake', 'https://dnr.wisconsin.gov/topic/parks/devilslake', 'America/Chicago', now()),
  ('Parfrey''s Glen', 'parfreys-glen', 'roadside-oddities', 43.40978, -89.63676, 'Merrimac', 'WI', 'A narrow sandstone-and-quartzite gorge shelters cool-climate plants and a stream that winds between high rock walls. Flooding has repeatedly changed the trail infrastructure, so visitors should expect a natural route rather than a manicured boardwalk.', 'open', 'https://dnr.wisconsin.gov/topic/Lands/naturalareas/index.asp?SNA=1', 'https://dnr.wisconsin.gov/', 'America/Chicago', now()),
  ('Pewit''s Nest State Natural Area', 'pewits-nest-state-natural-area', 'roadside-oddities', 43.46303, -89.79514, 'Baraboo', 'WI', 'Skillet Creek cuts through a narrow sandstone gorge filled with dark pools, ledges and small waterfalls. The fragile site has special rules and no cliff jumping; OddWay should route visitors only to legal trails and viewpoints.', 'open', 'https://dnr.wisconsin.gov/topic/Lands/naturalareas/index.asp?SNA=200', 'https://dnr.wisconsin.gov/', 'America/Chicago', now()),
  ('Natural Bridge and Rockshelter', 'natural-bridge-and-rockshelter', 'roadside-oddities', 43.34403, -89.92933, 'North Freedom', 'WI', 'A large sandstone arch spans a wooded hillside above a rock shelter used by people thousands of years ago. The combination of unusual geology and deep human history makes the small state park unusually dense with significance.', 'open', 'https://dnr.wisconsin.gov/topic/parks/naturalbridge', 'https://dnr.wisconsin.gov/topic/parks/naturalbridge', 'America/Chicago', now()),
  ('Roche-A-Cri State Park Petroglyphs', 'roche-a-cri-state-park-petroglyphs', 'weird-history', 44.00301, -89.81962, 'Friendship', 'WI', 'A sandstone outcrop rises abruptly above central Wisconsin and preserves Indigenous rock art along its base. A stairway also climbs the formation seasonally for long views, but visitors must stay off protected petroglyph surfaces.', 'limited', 'https://dnr.wisconsin.gov/topic/parks/rocheacri', 'https://dnr.wisconsin.gov/topic/parks/rocheacri', 'America/Chicago', now()),
  ('Mill Bluff State Park', 'mill-bluff-state-park', 'roadside-oddities', 43.94108, -90.31902, 'Camp Douglas', 'WI', 'Steep sandstone buttes rise from otherwise flat terrain, remnants of ancient sea stacks that became dramatic landmarks along today''s interstate corridor. A staircase climbs Mill Bluff for a view across the strange isolated formations.', 'open', 'https://dnr.wisconsin.gov/topic/parks/millbluff', 'https://dnr.wisconsin.gov/topic/parks/millbluff', 'America/Chicago', now()),
  ('Dells of the Wisconsin River State Natural Area', 'dells-of-the-wisconsin-river-state-natural-area', 'roadside-oddities', 43.68034, -89.79875, 'Wisconsin Dells', 'WI', 'Sandstone cliffs, narrow channels, pillars and side canyons line the Wisconsin River north of the tourist district. Much of the most dramatic scenery is easiest to see from the water, while protected natural-area lands require visitors to respect access rules.', 'limited', 'https://dnr.wisconsin.gov/topic/Lands/naturalareas/index.asp?SNA=109', 'https://dnr.wisconsin.gov/', 'America/Chicago', now()),
  ('Witches Gulch', 'witches-gulch', 'roadside-oddities', 43.66739, -89.78874, 'Wisconsin Dells', 'WI', 'A narrow slot-like sandstone gorge winds through mossy walls, boardwalks and unusual erosion forms. The property is generally experienced through Upper Dells boat tours rather than as a free independent hiking destination.', 'limited', 'https://www.dellsboats.com/', 'https://www.dellsboats.com/', 'America/Chicago', now()),
  ('Cherney Maribel Caves County Park', 'cherney-maribel-caves-county-park', 'roadside-oddities', 44.2864, -87.7706, 'Maribel', 'WI', 'Sinkholes, limestone caves, rock shelters and remnants of a historic stone hotel make this county park unusually varied. Cave access can be seasonal or guided to protect bats and fragile formations.', 'limited', 'https://manitowoccountywi.gov/departments/public-works/parks/cherney-maribel-caves-county-park/', 'https://manitowoccountywi.gov/', 'America/Chicago', now()),
  ('Cave Point County Park', 'cave-point-county-park', 'roadside-oddities', 44.93036, -87.17244, 'Sturgeon Bay', 'WI', 'Lake Michigan waves have carved caves, arches and undercut ledges into the limestone shoreline. On rough days water explodes through openings below the cliffs, but visitors must remain behind barriers and away from dangerous edges.', 'open', 'https://www.co.door.wi.gov/554/Cave-Point-County-Park', 'https://www.co.door.wi.gov/', 'America/Chicago', now()),
  ('Devil''s Punchbowl', 'devils-punchbowl', 'roadside-oddities', 44.85375, -91.94881, 'Menomonie', 'WI', 'A short trail descends into a cool sandstone amphitheater carved by water and weather. Mossy walls, overhangs and the bowl-shaped ravine create a miniature canyon hidden close to Menomonie.', 'open', 'https://www.dunncountywi.gov/', 'https://www.dunncountywi.gov/', 'America/Chicago', now()),
  ('Van Hise Rock', 'van-hise-rock', 'weird-history', 43.48944, -89.91528, 'Rock Springs', 'WI', 'This roadside quartzite outcrop played an important role in geologist Charles Van Hise''s work interpreting folded and metamorphosed rock layers. A scientific landmark sits almost directly beside the highway, turning a rock face into a stop in the history of geology.', 'open', 'https://dnr.wisconsin.gov/topic/parks/', 'https://www.wisconsinhistory.org/', 'America/Chicago', now()),
  ('Gibraltar Rock State Natural Area', 'gibraltar-rock-state-natural-area', 'roadside-oddities', 43.3431, -89.60032, 'Lodi', 'WI', 'A flat-topped sandstone bluff rises hundreds of feet above the surrounding countryside. Trails climb through forest to dramatic cliff views, creating a geological landmark that looks far more mountainous than its southern Wisconsin setting.', 'open', 'https://dnr.wisconsin.gov/topic/Lands/naturalareas/index.asp?SNA=73', 'https://dnr.wisconsin.gov/', 'America/Chicago', now()),
  ('Man Mound', 'man-mound', 'weird-history', 43.53085, -89.79561, 'Baraboo', 'WI', 'This surviving effigy mound was built in the shape of a human figure by Indigenous mound builders centuries ago. It is the only known anthropomorphic effigy mound in North America still largely intact, and a county park protects the site.', 'open', 'https://www.co.sauk.wi.us/parksandrecreation/man-mound-park', 'https://www.co.sauk.wi.us/', 'America/Chicago', now()),
  ('Aztalan State Park', 'aztalan-state-park', 'weird-history', 43.06604, -88.8611, 'Lake Mills', 'WI', 'Large platform mounds and reconstructed stockade sections mark the remains of a major Mississippian settlement occupied roughly a thousand years ago. The state''s most prominent archaeological park gives travelers a rare public look at monumental pre-contact earthworks.', 'open', 'https://dnr.wisconsin.gov/topic/parks/aztalan', 'https://dnr.wisconsin.gov/topic/parks/aztalan', 'America/Chicago', now()),
  ('Little Bohemia Lodge', 'little-bohemia-lodge', 'weird-history', 46.11957, -89.85748, 'Manitowish Waters', 'WI', 'In April 1934, federal agents attempted to capture John Dillinger and members of his gang at this remote lodge, leading to a chaotic gun battle. The restaurant still embraces the history, and bullet damage and memorabilia preserve one of the most famous episodes of the Dillinger manhunt.', 'open', 'https://www.littlebohemialodge.com/', 'https://www.littlebohemialodge.com/', 'America/Chicago', now()),
  ('Milton House Museum', 'milton-house-museum', 'weird-history', 42.77561, -88.94441, 'Milton', 'WI', 'This distinctive hexagonal 1844 inn is Wisconsin''s only certified Underground Railroad site. Guided tours interpret the Goodrich family, abolitionist activity and a concealed passage associated with people escaping slavery.', 'limited', 'https://miltonhouse.org/', 'https://miltonhouse.org/', 'America/Chicago', now()),
  ('Hearthstone Historic House Museum', 'hearthstone-historic-house-museum', 'weird-history', 44.2546, -88.4147, 'Appleton', 'WI', 'Built in 1882, Hearthstone became one of the first residences in the world powered by a centrally located hydroelectric station using the Edison system. Restored interiors preserve both Victorian domestic life and the startling early arrival of electric lighting.', 'limited', 'https://www.hearthstonemuseum.org/', 'https://www.hearthstonemuseum.org/', 'America/Chicago', now()),
  ('Black Point Estate and Gardens', 'black-point-estate-and-gardens', 'weird-history', 42.55248, -88.57763, 'Lake Geneva', 'WI', 'A wealthy Chicago brewing family built this Queen Anne summer estate above Geneva Lake in the 1880s. Many visitors arrive by boat, climb a long staircase from the shore and enter a house still packed with generations of family objects.', 'limited', 'https://blackpointestate.wisconsinhistory.org/', 'https://blackpointestate.wisconsinhistory.org/', 'America/Chicago', now()),
  ('Villa Louis', 'villa-louis', 'weird-history', 43.05877, -91.15825, 'Prairie du Chien', 'WI', 'This Victorian estate stands on St. Feriole Island at a site tied to the Dousman family, the fur trade and the long cultural history of Prairie du Chien. Restored interiors and outbuildings preserve an unusually complete upper-class nineteenth-century estate on the Mississippi frontier.', 'limited', 'https://villalouis.wisconsinhistory.org/', 'https://villalouis.wisconsinhistory.org/', 'America/Chicago', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as wisconsin from public.stops where state = 'WI';
